import * as orig from './dist/src/module.js';
import * as mig from './dist/out/module.js';
import assert from 'node:assert/strict';
const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = (xs) => xs[rnd(0, xs.length - 1)];
const LETTERS = 'abcdefghijklmnopqrstuvwxyz';
const NAMES = ['choi', 'kim', 'lee', 'park', 'jung'];
const randKey = () => Array.from({ length: rnd(1, 4) }, () => LETTERS[rnd(0, 25)]).join('');
function randScores() {
  const o = {}; const n = rnd(0, 5);
  for (let i = 0; i < n; i++) o[pick(NAMES.concat([randKey()]))] = rnd(-5, 99);
  return o;
}
function randRows() {
  return Array.from({ length: rnd(0, 12) }, () => ({ id: rnd(0, 9), name: pick(NAMES), age: rnd(18, 60) }));
}
function randJSON(depth) {
  const r = rnd(0, depth > 0 ? 6 : 3);
  switch (r) {
    case 0: return null;
    case 1: return Math.random() < 0.5;
    case 2: return rnd(-5, 99);
    case 3: return pick(['', 'red', 'a']);
    case 4: return Array.from({ length: rnd(0, 3) }, () => randJSON(depth - 1));
    default: { const o = {}; for (let i = rnd(0, 3); i > 0; i--) o[pick(['items', 'limits', 'enabled', 'x'])] = randJSON(depth - 1); return o; }
  }
}
const ex = {
  doubled: [{ choi: 50, kim: 79 }, { choi: 16, kim: 52, lee: 48 }],
  byNameKey: [[{ id: 4, name: 'choi', age: 21 }, { id: 9, name: 'choi', age: 55 }],
    [{ id: 1, name: 'choi', age: 28 }, { id: 8, name: 'kim', age: 44 }, { id: 1, name: 'lee', age: 52 }, { id: 2, name: 'lee', age: 35 }, { id: 9, name: 'lee', age: 53 }, { id: 8, name: 'choi', age: 56 }]],
  isBlank: [null, [{ items: 85, limits: null, enabled: 'red' }]],
};
let n = 0;
const check = (name, a, b) => { assert.deepStrictEqual(b, a); assert.equal(JSON.stringify(b), JSON.stringify(a)); n++; };
for (const a of ex.doubled) check('doubled', orig.doubled(a), mig.doubled(a));
for (const a of ex.byNameKey) check('byNameKey', orig.byNameKey(a), mig.byNameKey(a));
for (const a of ex.isBlank) check('isBlank', orig.isBlank(a), mig.isBlank(a));
for (let i = 0; i < 20000; i++) {
  const s = randScores(); check('doubled', orig.doubled(s), mig.doubled(s));
  const r = randRows(); check('byNameKey', orig.byNameKey(r), mig.byNameKey(r));
  const v = randJSON(2); check('isBlank', orig.isBlank(v), mig.isBlank(v));
}
// explicit primitive/edge cases in the isBlank range
for (const v of [null, true, false, 0, -5, 99, '', 'x', [], {}, [[]], [{}], {a:{}}, {a:[]}, [1], {a:1}, [null]]) check('isBlank', orig.isBlank(v), mig.isBlank(v));
console.log('all equal, checks:', n);
EOF
cd "$S" && node test.mjs

